#include "caocao/engine.hpp"
#include <fstream>
#include <iostream>
int main(int argc,char** argv){try{
 if(argc<2){std::cerr<<"usage: caocao_trace ASSETS [CHOICE] [--restore FILE | --snapshot-out FILE]\n";return 2;}
 caocao::Engine e(argv[1]);int choice=1;std::string restore,save;bool tutorial_terrain_snapshot=false,tutorial_menu_snapshot=false,tutorial_move_snapshot=false,tutorial_range_snapshot=false,tutorial_snapshot=false,tutorial_panel_snapshot=false,battle_snapshot=false,pose_snapshot=false,intro_snapshot=false,event_snapshot=false,reinforcement_snapshot=false,death_snapshot=false,next_turn_snapshot=false,fire_snapshot=false,summon_snapshot=false,confusion_snapshot=false;
 for(int i=2;i<argc;++i){std::string arg=argv[i];if(arg=="--tutorial-terrain-snapshot")tutorial_terrain_snapshot=true;else if(arg=="--tutorial-menu-snapshot")tutorial_menu_snapshot=true;else if(arg=="--tutorial-move-snapshot")tutorial_move_snapshot=true;else if(arg=="--tutorial-range-snapshot")tutorial_range_snapshot=true;else if(arg=="--tutorial-snapshot")tutorial_snapshot=true;else if(arg=="--tutorial-panel-snapshot")tutorial_panel_snapshot=true;else if(arg=="--confusion-snapshot")confusion_snapshot=true;else if(arg=="--restore"&&i+1<argc)restore=argv[++i];else if(arg=="--snapshot-out"&&i+1<argc)save=argv[++i];else if(arg=="--summon-snapshot")summon_snapshot=true;else if(arg=="--fire-snapshot")fire_snapshot=true;else if(arg=="--next-turn-snapshot")next_turn_snapshot=true;else if(arg=="--death-snapshot")death_snapshot=true;else if(arg=="--event-snapshot")event_snapshot=true;else if(arg=="--reinforcement-snapshot")reinforcement_snapshot=true;else if(arg=="--intro-snapshot")intro_snapshot=true;else if(arg=="--pose-snapshot")pose_snapshot=true;else if(arg=="--battle-snapshot")battle_snapshot=true;else choice=std::stoi(arg);}
 if(!restore.empty()){std::ifstream f(restore);if(!f)throw std::runtime_error("Snapshot not found");std::string raw((std::istreambuf_iterator<char>(f)),{});e.restore(raw);std::cout<<caocao::Json{{"restored_hash",e.state_hash()},{"state",e.state_json()}}.dump(2)<<'\n';return 0;}
 e.start_scenario(1);caocao::Json trace=caocao::Json::array();for(int n=0;n<5000;++n){const auto& s=e.state();trace.push_back({{"script",s.script},{"pc",s.pc},{"event",s.presentation},{"hash",e.state_hash()}});if(s.phase=="blocked")break;if(s.stable){if(!save.empty()&&(!tutorial_terrain_snapshot||(!s.tutorial.is_null()&&s.tutorial.at("ui").contains("panel_tile")))&&(!tutorial_menu_snapshot||s.presentation.value("type","")=="tutorial_command_menu")&&(!tutorial_move_snapshot||(!s.tutorial.is_null()&&s.units.at("0").at("battle").at("y")==0))&&(!tutorial_range_snapshot||(!s.tutorial.is_null()&&s.tutorial.at("ui").at("movement").get<bool>()))&&(!tutorial_snapshot||!s.tutorial.is_null())&&(!tutorial_panel_snapshot||(!s.tutorial.is_null()&&!s.tutorial.at("ui").at("panel").is_null()))&&(!confusion_snapshot||(s.turn==2&&s.units.contains("146")&&s.units.at("146").contains("battle")&&(s.units.at("146").at("battle").at("status").get<int>()&8)))&&(!summon_snapshot||s.mcall_resource==105)&&(!fire_snapshot||s.terrain_effects.at(0).at(4)==0)&&(!next_turn_snapshot||s.turn==2)&&(!death_snapshot||(s.phase=="battle_event"&&s.battle_phase==2&&s.script_fields.contains("ai_order")))&&(!event_snapshot||s.phase=="battle_event")&&(!reinforcement_snapshot||(s.phase=="battle_event"&&s.battle_phase==2))&&(!battle_snapshot||s.phase=="battle_intro")&&(!pose_snapshot||!s.battle_poses.empty())&&(!intro_snapshot||s.presentation.value("text","").starts_with("胜利条件"))){std::ofstream f(save);f<<e.serialize();if(!f)throw std::runtime_error("Snapshot output failed");save.clear();}e.submit({s.presentation.value("type","")=="tutorial_command_menu"?"tutorial_command":s.presentation.value("type","")=="choice"?"choose":"continue",s.presentation.value("type","")=="tutorial_command_menu"?255:choice});}else e.advance();}
 if(e.state().phase!="blocked")throw std::runtime_error("Trace limit reached without an explicit execution boundary");
 if(!save.empty())throw std::runtime_error("Requested snapshot point was not reached");
 std::cout<<caocao::Json{{"engine",caocao::engine_version},{"manifest",e.manifest_hash()},{"trace",trace},{"final_hash",e.state_hash()},{"diagnostic",e.state().diagnostic}}.dump(2)<<'\n';return 0;
}catch(const std::exception& ex){std::cerr<<ex.what()<<'\n';return 1;}}
